/* CP949 encoder for the CSV export (browsers only encode UTF-8).
   Covers ASCII, all 11,172 Hangul syllables, Hangul jamo and the KS X 1001 symbol set; Hanja and anything else -> '?'.
   Generated from Python's cp949 codec: 11172 syllables + 988 other characters. */
(function () {
  var SYL = '';
  var OTH = '';
  var syl = null, oth = null;
  function b64(s) {
    var bin = atob(s), out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  function init() {
    var a = b64(SYL);
    syl = new Uint16Array(a.length / 2);
    for (var i = 0; i < syl.length; i++) syl[i] = (a[2 * i] << 8) | a[2 * i + 1];
    var b = b64(OTH);
    oth = new Map();
    for (var j = 0; j < b.length; j += 4) oth.set((b[j] << 8) | b[j + 1], (b[j + 2] << 8) | b[j + 3]);
  }
  window.encodeCp949 = function (str) {
    if (!syl) init();
    var out = new Uint8Array(str.length * 2), n = 0;
    for (var i = 0; i < str.length; i++) {
      var c = str.charCodeAt(i), code = -1;
      if (c < 0x80) { out[n++] = c; continue; }
      if (c >= 0xAC00 && c <= 0xD7A3) code = syl[c - 0xAC00];
      else if (oth.has(c)) code = oth.get(c);
      else if (c >= 0xD800 && c <= 0xDBFF) i++; // surrogate pair (emoji etc.) -> single '?'
      if (code < 0) { out[n++] = 0x3f; continue; }
      out[n++] = code >> 8; out[n++] = code & 0xff;
    }
    return out.slice(0, n);
  };
})();
